the +ordered products.  It also records the trivial bound `4` on the state-dependent +distance of two square-summable families, used when the test error exceeds +one, and the elementary estimate collapsing the error terms `ε`, `√ε`, and +`(ε + √ε)^{1/4}` into a single power `ε^{1/8}` when `ε ≤ 1`. + +## References + +Paper `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:838-881` +(self-consistency and consistency with `M̂` in the proof of `lem:qld-4-10`), +blueprint `blueprint/src/chapter/ch15_qpbt_combining.tex:803-960`; the route +is explained in `docs/paper-gaps/qpbt_linearity-theorem-quotation.tex`. +-/ + +open scoped BigOperators Matrix MatrixOrder ComplexOrder + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT hiding Measurement +open MIPStarRE.Quantum DistanceCalculus + +noncomputable section + +/-! ## The trivial bound -/ + +/-- A square-summable family of operators has total squared norm at most one on +a unit vector. -/ +theorem sum_norm_apply_sq_le_one {α ι : Type*} [Fintype α] [Fintype ι] +    [DecidableEq ι] (A : α → Op ι) (ψ : EuclideanSpace ℂ ι) (hψ : ‖ψ‖ = 1) +    (hA : ∑ a, (A a)ᴴ * A a ≤ 1) : +    ∑ a, ‖applyOperatorToState (A a) ψ‖ ^ 2 ≤ 1 := by +  have h := sum_norm_mul_apply_le A 1 ψ hA +  simp only [mul_one, WinImplications.applyOperatorToState_one, hψ] at h +  simpa using h + +/-- The state-dependent distance of two square-summable families is at most +`4` on a unit vector, under a uniform distribution. -/ +theorem opFamilyDistSq_uniform_le_four {X α ι : Type*} [Fintype X] [DecidableEq X] +    [Nonempty X] [Fintype α] [Fintype ι] [DecidableEq ι] +    (A B : X → α → Op ι) (ψ : EuclideanSpace ℂ ι) (hψ : ‖ψ‖ = 1) +    (hA : ∀ x, ∑ a, (A x a)ᴴ * A x a ≤ 1) (hB : ∀ x, ∑ a, (B x a)ᴴ * B x a ≤ 1) : +    opFamilyDistSq (uniformDistribution X) A B ψ ≤ 4 := by +  unfold opFamilyDistSq +  calc avgOver (uniformDistribution X) (fun x => +        ∑ a, ‖applyOperatorToState (A x a - B x a) ψ‖ ^ 2) +      ≤ avgOver (uniformDistribution X) (fun _ => (4 : ℝ)) := by +        refine avgOver_mono _ _ _ fun x => ?_ +        have hA' := sum_norm_apply_sq_le_one (A x) ψ hψ (hA x) +        have hB' := sum_norm_apply_sq_le_one (B x) ψ hψ (hB x) +        have hpt : ∀ a, ‖applyOperatorToState (A x a - B x a) ψ‖ ^ 2 ≤ +            2 * ‖applyOperatorToState (A x a) ψ‖ ^ 2 + +              2 * ‖applyOperatorToState (B x a) ψ‖ ^ 2 := by +          intro a +          have hsub : applyOperatorToState (A x a - B x a) ψ = +              applyOperatorToState (A x a) ψ - applyOperatorToState (B x a) ψ := by +            simp [applyOperatorToState] +          rw [hsub] +          have := norm_sub_le (applyOperatorToState (A x a) ψ) +            (applyOperatorToState (B x a) ψ) +          nlinarith [norm_nonneg (applyOperatorToState (A x a) ψ), +            norm_nonneg (applyOperatorToState (B x a) ψ), +            norm_nonneg (applyOperatorToState (A x a) ψ - +              applyOperatorToState (B x a) ψ), +            sq_nonneg (‖applyOperatorToState (A x a) ψ‖ - +              ‖applyOperatorToState (B x a) ψ‖)] +        calc ∑ a, ‖applyOperatorToState (A x a - B x a) ψ‖ ^ 2 +            ≤ ∑ a, (2 * ‖applyOperatorToState (A x a) ψ‖ ^ 2 + +                2 * ‖applyOperatorToState (B x a) ψ‖ ^ 2) := +              Finset.sum_le_sum fun a _ => hpt a +          _ = 2 * ∑ a, ‖applyOperatorToState (A x a) ψ‖ ^ 2 + +                2 * ∑ a, ‖applyOperatorToState (B x a) ψ‖ ^ 2 := by +              rw [Finset.sum_add_distrib, Finset.mul_sum, Finset.mul_sum] +          _ ≤ 4 := by linarith +    _ = 4 := avgOver_uniform_const _ + +/-- The effects of a projective measurement, placed on a register pair, are +square-summable to the identity. -/ +theorem ProjectiveSetting.sum_place_effect_conjTranspose_mul_self_le_one +    {P : AdmissibleParams} {ε : ℝ} (S : ProjectiveSetting P ε) (p : Placement) +    {α : Type*} [Fintype α] (M : Measurement α (S.ExpandedLocalSpace p.side)) +    (hM : MIPStarRE.QPBT.Measurement.IsProjective M) : +    ∑ a, (S.place p (M.effect a))ᴴ * S.place p (M.effect a) ≤ 1 := by +  refine le_of_eq ?_ +  calc ∑ a, (S.place p (M.effect a))ᴴ * S.place p (M.effect a) +      = ∑ a, S.place p (M.effect a) := by +        refine Finset.sum_congr rfl fun a _ => ?_ +        rw [← S.place_conjTranspose, ← S.place_mul, +          (hM a).isSelfAdjoint.isHermitian.eq, (hM a).isIdempotentElem.eq] +    _ = 1 := by rw [← S.place_finsetSum, M.sum_eq_one, S.place_one] + +/-- The products `A_a B_b` of the effects of two projective measurements on a +common space are square-summable to the identity. -/ +theorem sum_mul_conjTranspose_mul_self_eq_one {α β ι : Type*} [Fintype α] +    [Fintype β] [Fintype ι] [DecidableEq ι] +    (A : Measurement α ι) (B : Measurement β ι) +    (hA : MIPStarRE.QPBT.Measurement.IsProjective A) +    (hB : MIPStarRE.QPBT.Measurement.IsProjective B) : +    ∑ ab : α × β, (A.effect ab.1 * B.effect ab.2)ᴴ * (A.effect ab.1 * B.effect ab.2) = +      1 := by +  have hpt : ∀ (a : α) (b : β), +      (A.effect a * B.effect b)ᴴ * (A.effect a * B.effect b) = +        B.effect b * A.effect a * B.effect b := by +    intro a b +    rw [Matrix.conjTranspose_mul, (hA a).isSelfAdjoint.isHermitian.eq, +      (hB b).isSelfAdjoint.isHermitian.eq, Matrix.mul_assoc _ _ (A.effect a * B.effect b), +      ← Matrix.mul_assoc (A.effect a) (A.effect a), (hA a).isIdempotentElem.eq, +      ← Matrix.mul_assoc] +  rw [Fintype.sum_prod_type_right] +  calc ∑ b : β, ∑ a : α, (A.effect a * B.effect b)ᴴ * (A.effect a * B.effect b) +      = ∑ b : β, B.effect b * (∑ a : α, A.effect a) * B.effect b := by +        refine Finset.sum_congr rfl fun b _ => ?_ +        rw [Finset.mul_sum, Finset.sum_mul] +        exact Finset.sum_congr rfl fun a _ => hpt a b +    _ = 1 := by +        simp_rw [A.sum_eq_one, mul_one] +        rw [Finset.sum_congr rfl fun b _ => (hB b).isIdempotentElem.eq] +        exact B.sum_eq_one + +/-- The products `B_b A_a` of the effects of two projective measurements on a +common space, indexed by the