/14_analysis_of_the_pauli_basis_test.tex:838-881`. -/ +theorem chain_bounds (S : ProjectiveSetting P ε) +    (Q : (side : PlayerSide) → PointPair P → +      Measurement (PauliScalar P × PauliScalar P) (S.ExpandedLocalSpace side)) +    (η C₁ C₂ C₃ : ℝ) +    (hQR : ∀ p : Placement, opFamilyDistSq (uniformDistribution (PointPair P)) +      (fun xz (ab : PauliScalar P × PauliScalar P) => +        S.place p ((Q p.side xz).effect ab)) +      (fun xz ab => S.place p ((S.sandwichPoint p.side xz.1 xz.2).effect ab)) +      S.psiHat ≤ η) +    (h₁ : ∀ p : Placement, opFamilyDistSq (uniformDistribution (PointPair P)) +      (fun xz (ab : PauliScalar P × PauliScalar P) => +        S.place p ((S.sandwichPoint p.side xz.1 xz.2).effect ab)) +      (fun xz ab => S.place p +        ((S.pointMeasExp p.side .Z xz.2).effect ab.2 * +          (S.pointMeasExp p.side .X xz.1).effect ab.1)) +      S.psiHat ≤ C₁ * Real.sqrt ε) +    (h₂ : ∀ p : Placement, opFamilyDistSq (uniformDistribution (PointPair P)) +      (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p +        ((S.pointMeasExp p.side .X xz.1).effect ab.1 * +          (S.pointMeasExp p.side .Z xz.2).effect ab.2)) +      (fun xz ab => S.place p +        ((S.pointMeasExp p.side .Z xz.2).effect ab.2 * +          (S.pointMeasExp p.side .X xz.1).effect ab.1)) +      S.psiHat ≤ C₂ * Real.sqrt ε) +    (h₃ : ∀ p₁ p₂ : Placement, p₁.IsOpposite p₂ → +      opFamilyDistSq (uniformDistribution (PointPair P)) +        (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p₁ +          ((S.pointMeasExp p₁.side .Z xz.2).effect ab.2 * +            (S.pointMeasExp p₁.side .X xz.1).effect ab.1)) +        (fun xz ab => S.place p₂ +          ((S.pointMeasExp p₂.side .X xz.1).effect ab.1 * +            (S.pointMeasExp p₂.side .Z xz.2).effect ab.2)) +        S.psiHat ≤ C₃ * ε) +    (p₁ p₂ : Placement) (hopp : p₁.IsOpposite p₂) : +    opFamilyDistSq (uniformDistribution (PointPair P)) +        (fun xz (ab : PauliScalar P × PauliScalar P) => +          S.place p₁ ((Q p₁.side xz).effect ab)) +        (fun xz ab => S.place p₂ +          ((S.pointMeasExp p₂.side .X xz.1).effect ab.1 * +            (S.pointMeasExp p₂.side .Z xz.2).effect ab.2)) +        S.psiHat ≤ 2 * η + 4 * (C₁ * Real.sqrt ε) + 4 * (C₃ * ε) ∧ +      opFamilyDistSq (uniformDistribution (PointPair P)) +        (fun xz (ab : PauliScalar P × PauliScalar P) => +          S.place p₁ ((Q p₁.side xz).effect ab)) +        (fun xz ab => S.place p₂ +          ((S.pointMeasExp p₂.side .Z xz.2).effect ab.2 * +            (S.pointMeasExp p₂.side .X xz.1).effect ab.1)) +        S.psiHat ≤ 4 * η + 8 * (C₁ * Real.sqrt ε) + 8 * (C₃ * ε) + +          2 * (C₂ * Real.sqrt ε) ∧ +      opFamilyDistSq (uniformDistribution (PointPair P)) +        (fun xz (ab : PauliScalar P × PauliScalar P) => +          S.place p₁ ((Q p₁.side xz).effect ab)) +        (fun xz ab => S.place p₂ ((Q p₂.side xz).effect ab)) +        S.psiHat ≤ 12 * η + 20 * (C₁ * Real.sqrt ε) + 16 * (C₃ * ε) + +          4 * (C₂ * Real.sqrt ε) := by +  -- `R_1 ≈ M^X M^Z` on the opposite placement +  have hRXZ := opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P)) +    _ _ _ S.psiHat _ _ (h₁ p₁) (h₃ p₁ p₂ hopp) +  -- `Q_1 ≈ M^X M^Z` on the opposite placement +  have hQXZ := opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P)) +    _ _ _ S.psiHat _ _ (hQR p₁) hRXZ +  -- `Q_1 ≈ M^Z M^X` on the opposite placement +  have hQZX := opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P)) +    _ _ _ S.psiHat _ _ hQXZ (h₂ p₂) +  -- `M^Z M^X ≈ Q_2` on the opposite placement +  have hZXQ : opFamilyDistSq (uniformDistribution (PointPair P)) +      (fun xz (ab : PauliScalar P × PauliScalar P) => S.place p₂ +        ((S.pointMeasExp p₂.side .Z xz.2).effect ab.2 * +          (S.pointMeasExp p₂.side .X xz.1).effect ab.1)) +      (fun xz ab => S.place p₂ ((Q p₂.side xz).effect ab)) +      S.psiHat ≤ 2 * η + 2 * (C₁ * Real.sqrt ε) := by +    rw [opFamilyDistSq_symm] +    exact opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P)) +      _ _ _ S.psiHat _ _ (hQR p₂) (h₁ p₂) +  have hQQ := opFamilyDistSq_le_of_le_of_le (uniformDistribution (PointPair P)) +    _ _ _ S.psiHat _ _ hQZX hZXQ +  refine ⟨by linarith, by linarith, by linarith⟩ + +end ProjectiveSetting + +/-! ## Collapsing the error terms into one power -/ + +/-- For `0 ≤ ε ≤ 1`, the error terms `ε`, `√ε`, and `(C₀ (ε + √ε))^{1/4}` +with `C₀ ≥ 1` are all bounded by multiples of `ε^{1/8}`. -/ +theorem error_terms_le_rpow_eighth {ε C₀ : ℝ} (hε : 0 ≤ ε) (hε1 : ε ≤ 1) +    (hC₀ : 1 ≤ C₀) : +    ε ≤ Real.rpow ε (1 / 8 : ℝ) ∧ Real.sqrt ε ≤ Real.rpow ε (1 / 8 : ℝ) ∧ +      Real.rpow (C₀ * (ε + Real.sqrt ε)) (1 / 4 : ℝ) ≤ +        2 * C₀ * Real.rpow ε (1 / 8 : ℝ) := by +  rcases eq_or_lt_of_le hε with h0 | hpos +  · subst h0 +    have h8 : Real.rpow (0 : ℝ) (1 / 8 : ℝ) = 0 := Real.zero_rpow (by norm_num) +    have h4 : Real.rpow (C₀ * (0 + Real.sqrt 0)) (1 / 4 : ℝ) = 0 := by +      rw [Real.sqrt_zero, add_zero, mul_zero] +      exact Real.zero_rpow (by norm_num) +    rw [h8, h4, Real.sqrt_zero] +    refine ⟨le_rfl, le_rfl, ?_⟩ +    positivity +  · have hsqrt : Real.sqrt ε = Real.rpow ε (1 / 2 : ℝ) := Real.sqrt_eq_rpow ε +    have hε1' : Real.rpow ε 1 = ε := Real.rpow_one ε +    have hmono : ∀ y z : ℝ, z ≤ y → Real.rpow ε y ≤ Real.rpow ε z := fun y z hyz => +      Real.rpow_le_rpow_of_exponent_ge hpos hε1 hyz +    refine ⟨?_, ?_, ?_⟩ +    · exact le_of_eq_of_le hε1'.symm (hmono 1 (1 / 8) (by norm_num)) +    · rw [hsqrt] +      exact hmono (1 / 2) (1 / 8) (by norm_num) +    · have hsum : ε + Real.sqrt ε ≤ 2 * Real.sqrt ε := by +        have : ε ≤ Real.sqrt ε := by +          rw [hsqrt] +          exact le_of_eq_of_le hε1'.symm (hmono 1 (1 / 2) (by norm_num)) +        linarith +      have hC : 0 ≤ 2 * C₀ := by linarith +      calc Real.rpow (C₀ * (ε + Real.sqrt ε)) (1 / 4 : ℝ) +          ≤ Real.rpow (2 * C₀ * Real.sqrt ε) (1 / 4 : ℝ) := by +            apply Real.rpow_le_rpow (by positivity) _ (by norm_num) +            nlinarith [Real.sqrt_nonneg ε] +        _ = Real.rpow (2 * C₀) (1 / 4 : ℝ) * Real.rpow ε (1 / 8 : ℝ) := by +            change (2 * C₀ * Real.sqrt ε) ^ (1 / 4 : ℝ) = +              (2 * C₀) ^ (1 / 4 : ℝ) * ε ^ (1 / 8 : ℝ) +            rw [Real.mul_rpow hC (Real.sqrt_nonneg ε), Real.sqrt_eq_rpow, +              ← Real.rpow_mul hε] +            norm_num +        _ ≤ 2 * C₀ * Real.rpow ε (1 / 8 : ℝ) := by +            refine mul_le_mul_of_nonneg_right ?_ (Real.rpow_nonneg hε _) +            calc Real.rpow (2 * C₀) (1 / 4 : ℝ) ≤ Real.rpow (2 * C₀) 1 := +                  Real.rpow_le_rpow_of_exponent_le (by linarith) (by norm_num) +              _ = 2 * C₀ := Real.rpow_one _ + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Points/Commutation.lean b/MIPStarRE/QPBT/Combining/Points/Commutation.lean new file mode 100644 index 00000000..29de3421 --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Points/Commutation.lean @@ -0,0 +1,457 @@ +import MIPStarRE.QPBT.Combining.Points.Placement + +/-! +# Approximate commutation of the field-valued expanded point measurements + +The approximate commutation of `lem:qld-comm-cons` is stated for the binary +refinements `M^{(Point,W),u,r}_b` of the expanded point measurements.  The +combined point measurements of `lem:qld-4-10` are built here directly from the +`F_q`-valued measurements `M^{(Point,W),u}_a`, so the commutation estimate is +transferred to them.  The transfer is exact: since +`M^{(Point,X),x}_a = E_r (-1)^{tr(ar)} X^r(x)` and +`M^{(Point,Z),z}_b = E_s (-1)^{tr(bs)} Z^s(z)`, the commutator of the two +measurement effects is the Fourier transform, in the outcome pair `(a, b)`, +of the commutators of the expanded observables, and Parseval's identity for +the additive characters of `F_q` turns the sum over `(a, b)` of the squared +norms into the average over `(r, s)` of the squared norms of the observable +commutators.  No factor depending on `q` is lost. + +## Main results + +* `sum_norm_sum_smul_sq_of_orthogonal`: Parseval's identity for an orthogonal +  system of coefficients. +* `sum_fixedCharacter_mul`: Fourier cancellation for the fixed trace character. +* `expPoint_comm`: the field-valued expanded point measurements approximately +  commute on every register placement, with the error of +  `lem:qld-comm-cons`. + +## References + +The commutation estimate for the binary refinements is item 2 of +`lem:qld-comm-cons`, blueprint +`blueprint/src/chapter/ch14_qpbt_observables.tex:1139-1210`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:466-505`; the +Fourier form of the point effects is `def:expanded-point-measurement`, paper +lines 384--418.  The role of the transfer in the proof of `lem:qld-4-10` is +explained in `docs/paper-gaps/qpbt_linearity-theorem-quotation.tex`. +-/ + +open scoped BigOperators Matrix MatrixOrder ComplexOrder + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT hiding Measurement +open MIPStarRE.Quantum +open MIPStarRE.LDT.Preliminaries + +noncomputable section + +/-- A pair of points, one for the `X` basis and one for the `Z` basis.  This +is the question pair `(x, z)` of `lem:qld-4-10`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:689-709`. -/ +abbrev PointPair (P : AdmissibleParams) := +  (Fin P.m → PauliScalar P) × (Fin P.m → PauliScalar P) + +/-! ## Parseval's identity for an orthogonal system of coefficients -/ + +/-- Formalization-only auxiliary for `lem:qld-4-10`: if the coefficient +vectors `i ↦ c j i`, `j` ranging over a finite set, are orthogonal with common +squared norm `N`, then the squared norms of the weighted sums +`∑ i, c j i • v i` add up to `N` times the squared norms of the `v i`. -/ +theorem sum_norm_sum_smul_sq_of_orthogonal {I J E : Type*} [Fintype I] +    [DecidableEq I] [Fintype J] [NormedAddCommGroup E] [InnerProductSpace ℂ E] +    (c : J → I → ℂ) (N : ℝ) +    (horth : ∀ i i', ∑ j, (starRingEnd ℂ) (c j i) * c j i' = +      if i = i' then (N : ℂ) else 0) +    (v : I → E) : +    ∑ j, ‖∑ i, c j i • v i‖ ^ 2 = N * ∑ i, ‖v i‖ ^ 2 := by +  have hnorm : ∀ x : E, ‖x‖ ^ 2 = (inner ℂ x x).re := fun x => by +    simpa using (inner_self_eq_norm_sq (𝕜 := ℂ) x).symm +  have hj : ∀ j, ‖∑ i, c j i • v i‖ ^ 2 = +      (∑ i, ∑ i', ((starRingEnd ℂ) (c j i) * c j i') * +        inner ℂ (v i) (v i')).re := by +    intro j +    rw [hnorm, sum_inner] +    simp only [inner_sum, inner_smul_left, inner_smul_right] +    congr 1 +    refine Finset.sum_congr rfl fun i _ => Finset.sum_congr rfl fun i' _ => ?_ +    ring +  have hsum : ∑ j, ∑ i, ∑ i', ((starRingEnd ℂ) (c j i) * c j i') * +      inner ℂ (v i) (v i') = ∑ i, (N : ℂ) * inner ℂ (v i) (v i) := by +    rw [Finset.sum_comm] +    refine Finset.sum_congr rfl fun i _ => ?_ +    rw [Finset.sum_comm] +    calc ∑ i', ∑ j, ((starRingEnd ℂ) (c j i) * c j i') * inner ℂ (v i) (v i') +        = ∑ i', (∑ j, (starRingEnd ℂ) (c j i) * c j i') * +            inner ℂ (v i) (v i') := by +          refine Finset.sum_congr rfl fun i' _ => ?_ +          rw [Finset.sum_mul] +      _ = ∑ i', (if i = i' then (N : ℂ) else 0) * inner ℂ (v i) (v i') := by +          refine Finset.sum_congr rfl fun i' _ => ?_ +          rw [horth] +      _ = (N : ℂ) * inner ℂ (v i) (v i) := by +          simp [ite_mul] +  calc ∑ j, ‖∑ i, c j i • v i‖ ^ 2 +      = (∑ j, ∑ i, ∑ i', ((starRingEnd ℂ) (c j i) * c j i') * +          inner ℂ (v i) (v i')).re := by +        rw [Complex.re_sum] +        exact Finset.sum_congr rfl fun j _ => hj j +    _ = (∑ i, (N : ℂ) * inner ℂ (v i) (v i)).re := by rw [hsum] +    _ = N * ∑ i, ‖v i‖ ^ 2 := by +        rw [Complex.re_sum, Finset.mul_sum] +        refine Finset.sum_congr rfl fun i _ => ?_ +        rw [Complex.re_ofReal_mul, ← hnorm] + +/-! ## The fixed trace character -/ + +section Characters + +variable {P : AdmissibleParams} + +/-- The phase induced by the fixed binary trace is an additive character. +Paper `references/qpbt-paper/04_preliminaries.tex:1052-1081`. -/ +theorem fixedCharacter_mul (x y : PauliScalar P) : +    phaseSign (fixedBinTrace P.model x) * phaseSign (fixedBinTrace P.model y) = +      phaseSign (fixedBinTrace P.model (x + y)) := by +  rw [fixedBinTrace, map_add, phaseSign_eq_ffChar, phaseSign_eq_ffChar, +    phaseSign_eq_ffChar] +  exact ((ZMod.stdAddChar (N := 2)).map_add_eq_mul _ _).symm + +/-- The fixed trace character is even: negation acts trivially on the binary +trace. -/ +theorem fixedCharacter_neg (x : PauliScalar P) : +    phaseSign (fixedBinTrace P.model (-x)) = +      phaseSign (fixedBinTrace P.model x) := by +  rw [fixedBinTrace, map_neg, ZMod.neg_eq_self_mod_two] + +/-- Fourier cancellation for the fixed trace character: the character sums to +the field size at `0` and to zero elsewhere.  This is `lem:cancellation` for +the one-dimensional space, blueprint +`blueprint/src/chapter/ch11_qpbt_algebra.tex:686`, paper +`references/qpbt-paper/04_preliminaries.tex:1124-1132`. -/ +theorem sum_fixedCharacter_mul (c : PauliScalar P) : +    ∑ a : PauliScalar P, phaseSign (fixedBinTrace P.model (a * c)) = +      if c = 0 then (Fintype.card (PauliScalar P) : ℂ) else 0 := by +  have h : (𝔼 r : PauliScalar P, phaseSign (fixedBinTrace P.model (r * c))) = +      if c = 0 then (1 : ℂ) else 0 := by +    simpa only [fixedBinTrace, phaseSign_eq_ffChar, +      MIPStarRE.LDT.Preliminaries.ffChar_apply] using +      (fourier_fact_scalar (p := 2) (F := PauliScalar P) c) +  rw [Finset.expect_eq_sum_div_card] at h +  have hcard : (Fintype.card (PauliScalar P) : ℂ) ≠ 0 := +    Nat.cast_ne_zero.mpr Fintype.card_ne_zero +  rw [Finset.card_univ, div_eq_iff hcard] at h +  rw [h] +  split_ifs <;> simp + +/-- Orthogonality of two fixed trace characters. -/ +theorem sum_fixedCharacter_mul_fixedCharacter (r r' : PauliScalar P) : +    ∑ a : PauliScalar P, phaseSign (fixedBinTrace P.model (a * r)) * +        phaseSign (fixedBinTrace P.model (a * r')) = +      if r = r' then (Fintype.card (PauliScalar P) : ℂ) else 0 := by +  have hterm : ∀ a : PauliScala