haracter_mul_fixedCharacter, +          sum_fixedCharacter_mul_fixedCharacter] +        by_cases h1 : rs.1 = rs'.1 <;> by_cases h2 : rs.2 = rs'.2 +        · rw [if_pos h1, if_pos h2, if_pos (Prod.ext h1 h2)] +          push_cast +          ring +        · rw [if_pos h1, if_neg h2, if_neg (fun h => h2 (congrArg Prod.snd h))] +          simp +        · rw [if_neg h1, if_pos h2, if_neg (fun h => h1 (congrArg Prod.fst h))] +          simp +        · rw [if_neg h1, if_neg h2, if_neg (fun h => h1 (congrArg Prod.fst h))] +          simp + +end Characters + +/-! ## Fourier form of the point effects and of their commutator -/ + +/-- A uniform operator average is the normalized sum. -/ +theorem averageOperatorOverDistribution_uniform_eq_inv_card_smul_sum +    {α ι : Type*} [Fintype α] [DecidableEq α] [Nonempty α] +    [Fintype ι] [DecidableEq ι] (f : α → Op ι) : +    averageOperatorOverDistribution (uniformDistribution α) f = +      (Fintype.card α : ℂ)⁻¹ • ∑ a, f a := by +  ext i j +  simp only [averageOperatorOverDistribution, uniformDistribution, +    Distribution.uniformOnFinset, Finset.mem_univ, if_true, Matrix.sum_apply, +    Matrix.smul_apply, Complex.real_smul, smul_eq_mul, +    Finset.card_univ, one_div, Complex.ofReal_inv, Complex.ofReal_natCast] +  rw [Finset.mul_sum] + +namespace ProjectiveSetting + +variable {P : AdmissibleParams} {ε : ℝ} + +/-- The Fourier form of an expanded point effect as a normalized character +sum of the expanded observables.  This is the first display of +`def:expanded-point-measurement`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:384-418`. -/ +theorem expPointOp_eq_inv_card_smul_sum (S : ProjectiveSetting P ε) +    (side : PlayerSide) (W : PauliKind) (u : Fin P.m → PauliScalar P) +    (a : PauliScalar P) : +    S.expPointOp side W u a = +      (Fintype.card (PauliScalar P) : ℂ)⁻¹ • +        ∑ r, phaseSign (fixedBinTrace P.model (a * r)) • S.expObs side W r u := by +  unfold expPointOp +  rw [averageOperatorOverDistribution_uniform_eq_inv_card_smul_sum] + +/-- Formalization-only auxiliary: the product of two normalized weighted sums +is the normalized double sum of the weighted products, indexed by pairs. -/ +theorem smul_sum_mul_smul_sum {ι K : Type*} [Fintype K] [Fintype ι] +    (c : ℂ) (α β : K → ℂ) (X Z : K → Op ι) : +    (c • ∑ r, α r • X r) * (c • ∑ s, β s • Z s) = +      (c * c) • ∑ rs : K × K, (α rs.1 * β rs.2) • (X rs.1 * Z rs.2) := by +  rw [Fintype.sum_prod_type, smul_mul_smul_comm, Finset.sum_mul_sum] +  congr 1 +  refine Finset.sum_congr rfl fun r _ => Finset.sum_congr rfl fun s _ => ?_ +  rw [smul_mul_smul_comm] + +/-- Formalization-only auxiliary: the product of two normalized weighted sums +in the opposite order, indexed by the same pairs. -/ +theorem smul_sum_mul_smul_sum_swap {ι K : Type*} [Fintype K] [Fintype ι] +    (c : ℂ) (α β : K → ℂ) (X Z : K → Op ι) : +    (c • ∑ s, β s • Z s) * (c • ∑ r, α r • X r) = +      (c * c) • ∑ rs : K × K, (α rs.1 * β rs.2) • (Z rs.2 * X rs.1) := by +  rw [Fintype.sum_prod_type_right, smul_mul_smul_comm, Finset.sum_mul_sum] +  congr 1 +  refine Finset.sum_congr rfl fun s _ => Finset.sum_congr rfl fun r _ => ?_ +  rw [smul_mul_smul_comm, mul_comm (β s)] + +/-- The commutator of two field-valued point effects is the Fourier transform +of the commutators of the expanded observables. -/ +theorem expPointOp_commutator_eq (S : ProjectiveSetting P ε) (side : PlayerSide) +    (x z : Fin P.m → PauliScalar P) (a b : PauliScalar P) : +    S.expPointOp side .X x a * S.expPointOp side .Z z b - +        S.expPointOp side .Z z b * S.expPointOp side .X x a = +      ((Fintype.card (PauliScalar P) : ℂ)⁻¹ * +          (Fintype.card (PauliScalar P) : ℂ)⁻¹) • +        ∑ rs : PauliScalar P × PauliScalar P, +          (phaseSign (fixedBinTrace P.model (a * rs.1)) * +              phaseSign (fixedBinTrace P.model (b * rs.2))) • +            (S.expObs side .X rs.1 x * S.expObs side .Z rs.2 z - +              S.expObs side .Z rs.2 z * S.expObs side .X rs.1 x) := by +  rw [expPointOp_eq_inv_card_smul_sum, expPointOp_eq_inv_card_smul_sum, +    smul_sum_mul_smul_sum, smul_sum_mul_smul_sum_swap, ← smul_sub, +    ← Finset.sum_sub_distrib] +  congr 1 +  refine Finset.sum_congr rfl fun rs _ => ?_ +  rw [smul_sub] + +/-- Formalization-only auxiliary: an operator applied to a state is linear in +the operator over finite sums. -/ +theorem applyOperatorToState_finsetSum {ι γ : Type*} [Fintype ι] [DecidableEq ι] +    (s : Finset γ) (M : γ → Op ι) (ψ : EuclideanSpace ℂ ι) : +    applyOperatorToState (∑ x ∈ s, M x) ψ = +      ∑ x ∈ s, applyOperatorToState (M x) ψ := by +  unfold applyOperatorToState +  simp only [map_sum, LinearMap.sum_apply] + +/-- Parseval transfer, pointwise in the point pair: the summed squared norms of +the placed commutators of the field-valued point effects equal the average over +`(r, s)` of the squared norms of the placed commutators of the expanded +observables. -/ +theorem sum_norm_place_expPointOp_commutator_sq (S : ProjectiveSetting P ε) +    (p : Placement) (x z : Fin P.m → PauliScalar P) : +    ∑ ab : PauliScalar P × PauliScalar P, +        ‖applyOperatorToState (S.place p +          (S.expPointOp p.side .X x ab.1 * S.expPointOp p.side .Z z ab.2 - +            S.expPointOp p.side .Z z ab.2 * S.expPointOp p.side .X x ab.1)) +          S.psiHat‖ ^ 2 = +      avgOver (uniformDistribution (PauliScalar P × PauliScalar P)) +        (fun rs => ‖applyOperatorToState (S.place p +          (S.expObs p.side .X rs.1 x * S.expObs p.side .Z rs.2 z - +            S.expObs p.side .Z rs.2 z * S.expObs p.side .X rs.1 x)) +          S.psiHat‖ ^ 2) := by +  set v : PauliScalar P × PauliScalar P → +      EuclideanSpace ℂ (SixReg P S.toStrategy.ιA S.toStrategy.ιB) := +    fun rs => applyOperatorToState (S.place p +      (S.expObs p.side .X rs.1 x * S.expObs p.side .Z rs.2 z - +        S.expObs p.side .Z rs.2 z * S.expObs p.side .X rs.1 x)) S.psiHat +  set c : ℂ := (Fintype.card (PauliScalar P) : ℂ)⁻¹ +  have hpt :